import com.luci.pianoroom.*;import java.io.*;import java.nio.*;import java.nio.file.*;
/** Deleting a disk library and its base handle must not invalidate live voice copies. */
public final class BankDeletionAudioTest {
 static void render(Synth s,ByteBuffer pcm)throws Exception {java.lang.reflect.Field l=Synth.class.getDeclaredField("layers"),f=Synth.class.getDeclaredField("fx");l.setAccessible(true);f.setAccessible(true);long[] v=(long[])l.get(s);java.lang.reflect.Method m=Synth.class.getDeclaredMethod("renderDirect",long.class,long.class,long.class,long.class,long.class,float.class,float.class,float.class,float.class,ByteBuffer.class,int.class);m.setAccessible(true);m.invoke(null,v[0],v[1],v[2],v[3],f.getLong(s),.8f,0f,0f,0f,pcm,256);}
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static void main(String[] args)throws Exception {File file=File.createTempFile("import-",args[0].endsWith("prb")?".prb":".sf2");Files.copy(new File(args[0]).toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING);long bank=Synth.load(file.getPath());check(bank!=0,"loaded bank");Synth synth=new Synth();try{synth.setLayer(0,bank,0);java.lang.reflect.Field running=Synth.class.getDeclaredField("running");running.setAccessible(true);((java.util.concurrent.atomic.AtomicBoolean)running.get(synth)).set(true);synth.midi(144,60,100);synth.midi(176,64,127);synth.midi(128,60,0);ByteBuffer pcm=ByteBuffer.allocateDirect(256*4).order(ByteOrder.nativeOrder());render(synth,pcm);Synth.freeBank(bank);bank=0;check(file.delete(),"delete source file");double energy=0;for(int block=0;block<80;block++){render(synth,pcm);for(int i=0;i<512;i++){short x=pcm.getShort(i*2);energy+=(double)x*x;}}check(energy>1000,"retained voice safely continues after disk/base deletion");synth.midi(176,64,0);System.out.println("PASS: library file/base removal preserves independent live voices and valid PCM.");}finally{if(bank!=0)Synth.freeBank(bank);synth.close();file.delete();}}
}
